INSERT INTO check_in_topics (topic_key, topic_name, description, category, depth_level, framework, prompt_questions, sort_order, review_status) VALUES
  ('work-life', 'Work and Life Balance', 'Is work leaving enough room for your life together?', 'wellbeing', 1, 'Stress spillover research', ARRAY['How has work been affecting your energy at home?', 'Is there a time work intrudes on us that you''d like to protect?', 'What''s one change that would help this month?']::text[], 210, 'draft'),
  ('friendships', 'Friends and Social Life', 'Are you both getting the social connection you need?', 'connection', 1, 'Social support research', ARRAY['Are you seeing your friends as much as you''d like?', 'Is there a friendship you''d like to invest in more, together or separately?', 'How much social time feels right for each of us right now?']::text[], 220, 'draft'),
  ('faith', 'Faith, Meaning and Beliefs', 'How do your beliefs and sense of meaning fit together?', 'values', 2, 'Gottman Method (shared meaning)', ARRAY['What gives your life meaning right now?', 'Are there beliefs or practices you''d like to share more — or give each other more space for?', 'How do we want our beliefs to show up in our home?']::text[], 230, 'draft'),
  ('family-planning', 'Children and Family Plans', 'Are you on the same page about children and family?', 'family', 3, 'Family planning communication', ARRAY['How are you feeling about children or family plans right now?', 'Has anything changed in what you want?', 'What would you like us to decide, and by when?']::text[], 240, 'draft'),
  ('security', 'Feeling Secure Together', 'Does the relationship feel steady and secure for both of you?', 'trust', 2, 'Attachment Theory', ARRAY['When do you feel most secure in us?', 'Has anything recently made you feel less secure?', 'What''s one reassurance that would help right now?']::text[], 250, 'draft'),
  ('forgiveness', 'Apologies and Forgiveness', 'How are you both at apologizing and letting go?', 'conflict', 3, 'Forgiveness research', ARRAY['Is there anything you''re still holding onto?', 'What makes an apology feel real to you?', 'Is there anything you''d like to apologize for?']::text[], 260, 'draft'),
  ('rest', 'Rest and Downtime', 'Is each of you getting enough rest and time to recharge?', 'wellbeing', 1, 'Dyadic coping research', ARRAY['How rested have you felt lately?', 'What kind of downtime helps you most?', 'How can we make sure we each get some this week?']::text[], 270, 'draft'),
  ('dreams', 'Dreams and Adventures', 'Are you making room for the things you dream of doing?', 'goals', 1, 'Self-expansion research', ARRAY['What''s on your bucket list that we haven''t talked about lately?', 'Is there an adventure we could plan for this year?', 'What''s one small step we could take toward it?']::text[], 280, 'draft'),
  ('hard-times', 'Grief and Hard Times', 'How are you both coping with anything heavy right now?', 'wellbeing', 3, 'Dual process model of grief', ARRAY['Is anything weighing on you that we haven''t talked about?', 'What kind of support helps you most when things are heavy?', 'Is there anyone else who could support us right now?']::text[], 290, 'draft'),
  ('sex-life', 'Our Sex Life', 'How is your physical relationship feeling for each of you?', 'intimacy', 3, 'Sexual communication research', ARRAY['What''s one thing you appreciate about our physical relationship?', 'Is there anything you''d like more of, less of, or to try?', 'What helps you feel relaxed and wanted?']::text[], 300, 'draft')
INSERT INTO deep_dive_themes (theme_key, title, summary, framework, focus_questions, weekly_activities, sort_order, review_status) VALUES
  ('play-adventure', 'Play and Adventure', 'A month of doing new things and laughing more together.', 'Self-expansion research', '["When do we laugh the most together?", "What''s something new we''ve always wanted to try?", "What did fun look like when we first met?", "How can we make play a regular part of life?"]'::jsonb, '[{"week": 1, "title": "Something new", "description": "Plan and do one activity neither of you has tried."}, {"week": 2, "title": "Game night", "description": "Hold a best-of-three game night with a silly prize."}, {"week": 3, "title": "Recreate a first", "description": "Recreate your first date or another early memory."}, {"week": 4, "title": "Bucket list", "description": "Brainstorm big dreams and add your favorites to your Bucket List."}]'::jsonb, 90, 'draft'),
  ('family-traditions', 'Family and Traditions', 'A month of shaping the traditions and family culture you want.', 'Family systems practice', '["What traditions from each of our families do we want to keep?", "Which ones would we rather let go?", "How do we want to handle holidays with extended family?", "What''s a new tradition that would feel like ours?"]'::jsonb, '[{"week": 1, "title": "Family stories", "description": "Share a favorite tradition from each of your childhoods."}, {"week": 2, "title": "Keep and let go", "description": "Choose one tradition to keep and one to adapt or drop."}, {"week": 3, "title": "Holiday plan", "description": "Agree on how you''ll handle the next holiday with family."}, {"week": 4, "title": "A new tradition", "description": "Start one brand-new tradition of your own."}]'::jsonb, 100, 'draft'),
  ('growing-together', 'Growing Individually, Together', 'A month of supporting each other''s personal goals.', 'Self-expansion research', '["What''s something each of us is working on for ourselves?", "How do we like to be supported in our goals?", "What gets in the way of personal growth right now?", "How has each of us grown since we met?"]'::jsonb, '[{"week": 1, "title": "Growth goals", "description": "Each share one personal goal for the next six months."}, {"week": 2, "title": "Support plan", "description": "Each say what support would actually help, and agree on it."}, {"week": 3, "title": "Progress check", "description": "Check in on progress and celebrate small steps."}, {"week": 4, "title": "Grown together", "description": "Share how you''ve each seen the other grow."}]'::jsonb, 110, 'draft'),
  ('rest-rhythm', 'Rest and Rhythm', 'A month of protecting rest, balance and unhurried time together.', 'Stress spillover research', '["How rested do we each feel right now?", "Where does work or busyness crowd out our time together?", "What kind of rest helps each of us most?", "What rhythm would feel sustainable?"]'::jsonb, '[{"week": 1, "title": "Energy check", "description": "Each rate your energy and name what drains and restores it."}, {"week": 2, "title": "Protected time", "description": "Choose one screen-free, work-free evening and keep it."}, {"week": 3, "title": "Say no to one thing", "description": "Each drop or postpone one commitment to make room."}, {"week": 4, "title": "Design a rhythm", "description": "Agree on a daily, weekly and monthly rhythm that feels sustainable."}]'::jsonb, 120, 'draft')
